CREATE TYPE public.app_role AS ENUM ('admin','editor','reporter');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,name text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL DEFAULT 'reporter');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.is_news_editor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','editor')) $$;
GRANT EXECUTE ON FUNCTION public.is_news_editor() TO authenticated,anon,service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_news_editor());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_news_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email,name) VALUES(NEW.id,NEW.email,coalesce(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END $$;
CREATE TRIGGER news_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_news_profile();
CREATE TABLE public.categories(id text PRIMARY KEY,names jsonb NOT NULL,sort_order int NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_read ON public.categories FOR SELECT TO anon,authenticated USING(active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY categories_admin ON public.categories FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.settings(id int PRIMARY KEY DEFAULT 1 CHECK(id=1),site_name text NOT NULL DEFAULT 'TAK TV India',site_url text NOT NULL DEFAULT '',taglines jsonb NOT NULL DEFAULT '{"en":"Truth without Delay","hi":"बिना देरी के सच","te":"ఆలస్యం లేకుండా నిజం"}',email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',youtube text NOT NULL DEFAULT '',facebook text NOT NULL DEFAULT '',x text NOT NULL DEFAULT '',instagram text NOT NULL DEFAULT '',whatsapp text NOT NULL DEFAULT '');
GRANT SELECT ON public.settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.settings TO authenticated; GRANT ALL ON public.settings TO service_role; ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.settings FOR SELECT TO anon,authenticated USING(true); CREATE POLICY settings_admin ON public.settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.articles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lang text NOT NULL DEFAULT 'en' CHECK(lang IN ('en','hi','te')),title text NOT NULL DEFAULT '',slug text NOT NULL,summary text NOT NULL DEFAULT '',body_html text NOT NULL DEFAULT '',category_id text REFERENCES public.categories(id),cover_path text NOT NULL DEFAULT '',cover_alt text NOT NULL DEFAULT '',cover_credit text NOT NULL DEFAULT '',youtube_id text NOT NULL DEFAULT '',is_breaking boolean NOT NULL DEFAULT false,is_featured boolean NOT NULL DEFAULT false,reporter_name text NOT NULL DEFAULT '',location text NOT NULL DEFAULT '',tags text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','scheduled','published','archived','trashed')),publish_at timestamptz,published_at timestamptz,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),seo_title text NOT NULL DEFAULT '',seo_description text NOT NULL DEFAULT '',editor_note text NOT NULL DEFAULT '',pending_edits jsonb,published_slug text,UNIQUE(lang,slug));
GRANT SELECT(id,lang,title,slug,summary,body_html,category_id,cover_path,cover_alt,cover_credit,youtube_id,is_breaking,is_featured,reporter_name,location,tags,status,publish_at,published_at,created_at,updated_at,seo_title,seo_description) ON public.articles TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.articles TO authenticated; GRANT ALL ON public.articles TO service_role; ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
CREATE POLICY articles_public ON public.articles FOR SELECT TO anon,authenticated USING((status='published' AND published_at<=now()) OR (status='scheduled' AND publish_at<=now()));
CREATE POLICY articles_private ON public.articles FOR SELECT TO authenticated USING(public.is_news_editor() OR created_by=auth.uid());
CREATE POLICY articles_create ON public.articles FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()));
CREATE POLICY articles_update ON public.articles FOR UPDATE TO authenticated USING(public.is_news_editor() OR (created_by=auth.uid() AND status IN ('draft','review'))) WITH CHECK(public.is_news_editor() OR (created_by=auth.uid() AND status IN ('draft','review')));
CREATE POLICY articles_delete ON public.articles FOR DELETE TO authenticated USING(public.is_news_editor());
CREATE INDEX news_public_index ON public.articles(lang,status,published_at DESC); CREATE INDEX news_category_index ON public.articles(category_id,lang);
CREATE TABLE public.media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),path text NOT NULL UNIQUE,thumb_path text NOT NULL DEFAULT '',alt text NOT NULL DEFAULT '',credit text NOT NULL DEFAULT '',original_name text NOT NULL DEFAULT '',width int NOT NULL DEFAULT 0,height int NOT NULL DEFAULT 0,size int NOT NULL DEFAULT 0,uploaded_by uuid NOT NULL,uploaded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.media TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.media TO authenticated; GRANT ALL ON public.media TO service_role; ALTER TABLE public.media ENABLE ROW LEVEL SECURITY;
CREATE POLICY media_public ON public.media FOR SELECT TO anon USING(EXISTS(SELECT 1 FROM public.articles a WHERE a.cover_path=media.path AND ((a.status='published' AND a.published_at<=now()) OR (a.status='scheduled' AND a.publish_at<=now()))));
CREATE POLICY media_staff_read ON public.media FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()));
CREATE POLICY media_upload ON public.media FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()));
CREATE POLICY media_edit ON public.media FOR UPDATE TO authenticated USING(public.is_news_editor()); CREATE POLICY media_delete ON public.media FOR DELETE TO authenticated USING(public.is_news_editor() AND NOT EXISTS(SELECT 1 FROM public.articles a WHERE a.cover_path=media.path OR a.body_html LIKE '%'||media.path||'%'));
CREATE TABLE public.redirects(lang text NOT NULL,old_slug text NOT NULL,new_slug text NOT NULL,PRIMARY KEY(lang,old_slug));
GRANT SELECT ON public.redirects TO anon,authenticated; GRANT ALL ON public.redirects TO service_role; ALTER TABLE public.redirects ENABLE ROW LEVEL SECURITY; CREATE POLICY redirects_read ON public.redirects FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.removed_stories(lang text NOT NULL,slug text NOT NULL,PRIMARY KEY(lang,slug));
GRANT SELECT ON public.removed_stories TO anon,authenticated; GRANT ALL ON public.removed_stories TO service_role; ALTER TABLE public.removed_stories ENABLE ROW LEVEL SECURITY; CREATE POLICY removed_read ON public.removed_stories FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.pages(id text PRIMARY KEY,title text NOT NULL,body_html text NOT NULL DEFAULT '');
GRANT SELECT ON public.pages TO anon; GRANT SELECT,INSERT,UPDATE ON public.pages TO authenticated; GRANT ALL ON public.pages TO service_role; ALTER TABLE public.pages ENABLE ROW LEVEL SECURITY; CREATE POLICY pages_read ON public.pages FOR SELECT TO anon,authenticated USING(true); CREATE POLICY pages_admin ON public.pages FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_news_article() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.is_news_editor() THEN
  IF NOT public.has_role(auth.uid(),'reporter') OR NEW.created_by<>auth.uid() OR NEW.status NOT IN ('draft','review') THEN RAISE EXCEPTION 'Reporters cannot publish, schedule or remove stories'; END IF;
 END IF;
 IF TG_OP='UPDATE' THEN IF NEW.created_by<>OLD.created_by THEN RAISE EXCEPTION 'Owner cannot change'; END IF; IF OLD.published_at IS NOT NULL AND NEW.lang<>OLD.lang THEN RAISE EXCEPTION 'Published language cannot change'; END IF; END IF;
 IF NEW.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' OR length(NEW.slug)<3 OR length(NEW.slug)>80 THEN RAISE EXCEPTION 'Web address must be 3–80 lowercase letters, numbers and hyphens'; END IF;
 IF NEW.status IN ('published','scheduled') THEN
  IF length(trim(NEW.title))=0 OR NEW.category_id IS NULL THEN RAISE EXCEPTION 'Headline and category are required'; END IF;
  IF length(regexp_replace(NEW.body_html,'<[^>]*>','','g'))<40 AND NEW.youtube_id='' THEN RAISE EXCEPTION 'Story needs at least 40 characters or a video'; END IF;
  IF NEW.cover_path<>'' AND trim(NEW.cover_alt)='' THEN RAISE EXCEPTION 'Cover photo caption is required'; END IF;
  IF NEW.youtube_id<>'' AND NEW.youtube_id !~ '^[A-Za-z0-9_-]{11}$' THEN RAISE EXCEPTION 'Invalid YouTube link'; END IF;
  IF NEW.status='scheduled' AND NEW.publish_at IS NULL THEN RAISE EXCEPTION 'Publish time is required'; END IF;
  IF NEW.status='published' AND NEW.published_at IS NULL THEN NEW.published_at=now(); END IF;
  IF NEW.summary='' THEN NEW.summary=left(regexp_replace(NEW.body_html,'<[^>]*>','','g'),160); END IF;
 END IF;
 NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_news BEFORE INSERT OR UPDATE ON public.articles FOR EACH ROW EXECUTE FUNCTION public.validate_news_article();
CREATE FUNCTION public.track_news_urls() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_OP='UPDATE' AND OLD.published_at IS NOT NULL AND NEW.slug<>OLD.slug THEN INSERT INTO public.redirects VALUES(OLD.lang,OLD.slug,NEW.slug) ON CONFLICT(lang,old_slug) DO UPDATE SET new_slug=excluded.new_slug; UPDATE public.redirects SET new_slug=NEW.slug WHERE lang=NEW.lang AND new_slug=OLD.slug; END IF;
 IF TG_OP='DELETE' THEN IF OLD.published_at IS NOT NULL THEN INSERT INTO public.removed_stories VALUES(OLD.lang,OLD.slug) ON CONFLICT DO NOTHING; END IF; RETURN OLD; END IF;
 IF NEW.status IN ('draft','archived','trashed') AND NEW.published_at IS NOT NULL THEN INSERT INTO public.removed_stories VALUES(NEW.lang,NEW.slug) ON CONFLICT DO NOTHING; ELSIF NEW.status IN ('published','scheduled') THEN DELETE FROM public.removed_stories WHERE lang=NEW.lang AND slug=NEW.slug; END IF; RETURN NEW; END $$;
CREATE TRIGGER track_news AFTER INSERT OR UPDATE OR DELETE ON public.articles FOR EACH ROW EXECUTE FUNCTION public.track_news_urls();
CREATE POLICY news_files_staff_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='news-media' AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()));
CREATE POLICY news_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='news-media' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('webp','jpg','jpeg','png') AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()));
CREATE POLICY news_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='news-media' AND public.is_news_editor() AND NOT EXISTS(SELECT 1 FROM public.articles WHERE cover_path=name OR body_html LIKE '%'||name||'%'));
CREATE POLICY news_files_public ON storage.objects FOR SELECT TO anon USING(bucket_id='news-media' AND EXISTS(SELECT 1 FROM public.articles a WHERE ((a.status='published' AND a.published_at<=now()) OR (a.status='scheduled' AND a.publish_at<=now())) AND (a.cover_path=name OR a.body_html LIKE '%'||name||'%')));